import React,{useEffect,useRef,useState} from 'react';
import {Link,Navigate,Route,Routes,useLocation,useNavigate,useParams} from 'react-router-dom';
import Hls from 'hls.js';

type Episode={id:string;name:string;lineName:string;url:string;type:string;sortOrder:number};
type Video={id:string;sourceKey:string;title:string;cover?:string;year?:number;category?:string;area?:string;language?:string;desc?:string;director?:string;actors?:string;sourceName?:string;episodes?:Episode[]};
type User={id:number;username:string;displayName?:string;avatarUrl?:string;role:string;pageAccess:string;sourceKeys:string[]};
type Settings=Record<string,string>;
const API_BASE=import.meta.env.VITE_API_URL||'';
const getCache=new Map<string,{expires:number,value:any}>();const getInflight=new Map<string,Promise<any>>();
async function api<T=any>(url:string,options?:RequestInit):Promise<T>{const method=options?.method||'GET';const cacheable=method==='GET'&&url.startsWith('/sources/');if(cacheable){const hit=getCache.get(url);if(hit&&hit.expires>Date.now())return hit.value as T;const active=getInflight.get(url);if(active)return active as Promise<T>}const task=(async()=>{const response=await fetch(API_BASE+'/api'+url,{credentials:'include',...options});const text=await response.text();let body:any={};try{body=text?JSON.parse(text):{}}catch{throw new Error(`服务器返回了网页而不是 JSON（${response.status}）`)}if(!response.ok)throw new Error(body.error||'请求失败');if(cacheable)getCache.set(url,{expires:Date.now()+(url.includes('/videos/')?600000:120000),value:body});return body as T})();if(cacheable){getInflight.set(url,task);task.finally(()=>getInflight.delete(url))}return task}
const prefetchDetail=(video:Video)=>api(`/sources/${video.sourceKey}/videos/${video.id}`).catch(()=>{});
const normalizeCategory=(value:string)=>String(value||'').toLowerCase().replace(/[\s_\-—·/\\,，、:：()（）【】\[\]]/g,'').replace(/片$|剧$|类$|节目$/g,'');const categoryAliases:Record<string,string>={'国漫':'动漫','国产动画':'动漫','国产动漫':'动漫','番剧':'动漫','大陆剧':'国产剧','国产电视剧':'国产剧','内地剧':'国产剧','香港剧':'港剧','台湾剧':'台剧','美剧':'欧美剧','英剧':'欧美剧','韩剧':'日韩剧','日剧':'日韩剧','综艺节目':'综艺','真人秀':'综艺','脱口秀':'综艺'};const guessCategory=(remote:string,locals:string[])=>{const alias=categoryAliases[String(remote).trim()]||String(remote).trim(),a=normalizeCategory(alias);return locals.find(x=>normalizeCategory(x)===a)||locals.find(x=>a.length>=2&&(a.includes(normalizeCategory(x))||normalizeCategory(x).includes(a)))||''};
const hydrateMissingCovers=<S extends Video[]|undefined>(items:Video[],setItems:React.Dispatch<React.SetStateAction<S>>)=>items.filter(x=>!x.cover).slice(0,60).forEach(video=>{api<Video>(`/sources/${video.sourceKey}/videos/${video.id}`).then(detail=>{if(detail.cover)setItems(current=>(current?current.map(x=>x.id===video.id?{...x,cover:detail.cover,desc:detail.desc||x.desc}:x):current) as S)}).catch(()=>{})});
const json=(data:any):RequestInit=>({method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});
const lineLabel=(name:string)=>{try{return JSON.parse(localStorage.getItem('tvbox.lineAliases')||'{}')[name]||name}catch{return name}};
const timeAgo=(value:string)=>{const s=Math.max(1,Math.floor((Date.now()-new Date(value).getTime())/1000));if(s<60)return '刚刚';if(s<3600)return `${Math.floor(s/60)} 分钟前`;if(s<86400)return `${Math.floor(s/3600)} 小时前`;return `${Math.floor(s/86400)} 天前`};
function Avatar({user,large=false}:{user?:Partial<User>;large?:boolean}){return <span className={`avatar ${large?'avatar-large':''}`}><img src={user?.avatarUrl||'/images/default-avatar.svg'} alt="用户头像" onError={e=>{e.currentTarget.src='/images/default-avatar.svg'}}/></span>}
function Spinner({label='正在加载'}:{label?:string}){return <div className="state-box"><span className="spinner"/><p>{label}</p></div>}
function Empty({title,detail}:{title:string;detail?:string}){return <div className="empty-state"><b>◇</b><h3>{title}</h3>{detail&&<p>{detail}</p>}</div>}
function Progress({value}:{value:number}){return <span className="progress"><i style={{width:`${Math.min(100,Math.max(0,value))}%`}}/></span>}
function Poster({src,title}:{src?:string;title:string}){const [failed,setFailed]=useState(false);useEffect(()=>setFailed(false),[src]);return failed||!src?<span className="poster-fallback">{title.slice(0,1)}</span>:<img loading="eager" decoding="async" fetchPriority="high" src={src} alt={title} onError={()=>setFailed(true)}/>}
function MovieCard({video,progress}:{video:Video;progress?:number}){const timer=useRef<number|undefined>(undefined);const enter=()=>{if(matchMedia('(hover:hover)').matches)timer.current=window.setTimeout(()=>void prefetchDetail(video),400)};const leave=()=>clearTimeout(timer.current);return <Link className="movie-card" to={`/detail/${video.sourceKey}/${video.id}`} onMouseEnter={enter} onMouseLeave={leave} onFocus={enter} onBlur={leave}><div className="movie-poster"><Poster src={video.cover} title={video.title}/><div className="movie-actions"><span>▶</span><span>＋</span></div>{video.year&&<small>{video.year}</small>}{progress!==undefined&&<Progress value={progress}/>}</div><strong>{video.title}</strong><span>{video.category||video.area||'影视'}</span></Link>}
function Rail({title,items,progress}:{title:string;items:Video[];progress?:Record<string,number>}){if(!items.length)return null;return <section className="rail"><div className="rail-head"><h2>{title}</h2><span>{items.length} 部</span></div><div className="rail-track">{items.map(v=><MovieCard key={v.id} video={v} progress={progress?.[v.id]}/>)}</div></section>}
function Page({title,eyebrow,children}:{title:string;eyebrow?:string;children:React.ReactNode}){return <div className="content-page"><div className="page-heading"><small>{eyebrow}</small><h1>{title}</h1></div>{children}</div>}
function Guard({user,admin=false,children}:{user:User|null|undefined;admin?:boolean;children:React.ReactNode}){if(user===undefined)return <Spinner label="正在验证登录状态"/>;if(!user)return <Navigate to="/login" replace/>;if(admin&&user.role!=='admin')return <Navigate to="/" replace/>;return <>{children}</>}
function HomeSkeleton(){return <div className="home-skeleton" aria-label="正在准备首页"><div className="skeleton-hero"><i/><i/><i/></div><div className="skeleton-content"><i/><div>{Array.from({length:7},(_,i)=><span key={i}/>)}</div><i/><div>{Array.from({length:7},(_,i)=><span key={i}/>)}</div></div></div>}

function Login({settings}:{settings:Settings}){const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setMessage('');try{await api('/auth/login',json({username,password}));location.href='/'}catch(error:any){setMessage(error.message)}finally{setBusy(false)}};return <div className="login-screen"><div className="login-backdrop"/><form className="login-panel" onSubmit={submit}><Link className="login-logo" to="/"><img src={settings.logoUrl||'/images/dabiao-logo.svg'} alt={settings.siteName||'大彪TV'}/></Link><h1>欢迎回来</h1><p>登录后继续你的观影旅程</p><label>账号<input required value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username"/></label><label>密码<input required type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></label><div className="session-note">安全登录状态将自动保持 30 天</div><button className="primary wide" disabled={busy}>{busy?'正在登录…':'登录'}</button>{message&&<p className="form-error">{message}</p>}</form></div>}
function Install({settings,status}:{settings:Settings;status:any}){const [username,setUsername]=useState('admin');const [password,setPassword]=useState('');const [confirmPassword,setConfirmPassword]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const submit=async(e:React.FormEvent)=>{e.preventDefault();setBusy(true);setMessage('');try{await api('/install',json({username,password,confirmPassword}));location.href='/'}catch(error:any){setMessage(error.message)}finally{setBusy(false)}};return <div className="login-screen"><div className="login-backdrop"/><form className="login-panel" onSubmit={submit}><div className="login-logo"><img src={settings.logoUrl||'/images/dabiao-logo.svg'} alt={settings.siteName||'大彪TV'}/></div><h1>首次安装</h1><p>检查环境后创建唯一管理员账号</p><div className="session-note">数据库：{status?.database?.provider||'SQLite'} · {status?.database?.writable?'连接正常，可写入':'无法写入'}<br/>数据位置：{status?.database?.url||'未设置'}<br/>Node.js：{status?.node||'未知'}</div><label>管理员账号<input required minLength={3} value={username} onChange={e=>setUsername(e.target.value)} autoComplete="username"/></label><label>管理员密码<input required minLength={8} type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="new-password"/></label><label>确认密码<input required minLength={8} type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)} autoComplete="new-password"/></label><div className="session-note">密码只保存为不可逆哈希；安装完成后本页面会自动失效。数据库连接由启动前的 `.env` 中 `DATABASE_URL` 决定。</div><button className="primary wide" disabled={busy}>{busy?'正在初始化…':'完成安装并登录'}</button>{message&&<p className="form-error">{message}</p>}</form></div>}
function UserMenu({user,onLogout}:{user:User;onLogout:()=>void}){const [open,setOpen]=useState(false);const ref=useRef<HTMLDivElement>(null);useEffect(()=>{const click=(e:MouseEvent)=>{if(!ref.current?.contains(e.target as Node))setOpen(false)};const key=(e:KeyboardEvent)=>{if(e.key==='Escape')setOpen(false)};document.addEventListener('mousedown',click);document.addEventListener('keydown',key);return()=>{document.removeEventListener('mousedown',click);document.removeEventListener('keydown',key)}},[]);return <div className="user-menu" ref={ref}><button aria-label="打开用户菜单" aria-expanded={open} onClick={()=>setOpen(!open)}><Avatar user={user}/><span>⌄</span></button>{open&&<div className="user-dropdown"><div className="user-card"><Avatar user={user}/><div><b>{user.displayName||user.username}</b><small>{user.role==='admin'?'管理员':'普通用户'}</small></div></div><Link to="/profile" onClick={()=>setOpen(false)}>个人中心</Link><Link to="/profile?tab=continue" onClick={()=>setOpen(false)}>继续观看</Link><Link to="/history" onClick={()=>setOpen(false)}>观看历史</Link><Link to="/favorites" onClick={()=>setOpen(false)}>我的收藏</Link>{user.role==='admin'&&<Link to="/admin" onClick={()=>setOpen(false)}>管理后台</Link>}<button className="logout" onClick={onLogout}>退出登录</button></div>}</div>}
function Header({user,settings,onLogout}:{user:User|null;settings:Settings;onLogout:()=>void}){const nav=useNavigate();const [query,setQuery]=useState('');const [scrolled,setScrolled]=useState(false);useEffect(()=>{const f=()=>setScrolled(scrollY>18);addEventListener('scroll',f);return()=>removeEventListener('scroll',f)},[]);return <><header className={`site-header ${scrolled?'scrolled':''}`}><Link className="brand" to="/"><img src={settings.logoUrl||'/images/dabiao-logo.svg'} alt={settings.siteName||'大彪TV'} onError={e=>{e.currentTarget.src='/images/dabiao-logo.svg'}}/></Link><nav><Link to="/">首页</Link><Link to="/sources">片库</Link><Link to="/search?q=电影">电影</Link><Link to="/search?q=电视剧">电视剧</Link><Link to="/search?q=动漫">动漫</Link></nav><form className="header-search" onSubmit={e=>{e.preventDefault();if(query.trim())nav('/search?q='+encodeURIComponent(query.trim()))}}><span>⌕</span><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索影视、演员、导演"/></form><div className="header-icons"><Link aria-label="观看历史" to="/history">◷</Link><Link aria-label="收藏" to="/favorites">♡</Link>{user?<UserMenu user={user} onLogout={onLogout}/>:<Link className="login-link" to="/login">登录</Link>}</div></header><nav className="mobile-nav"><Link to="/">⌂<span>首页</span></Link><Link to="/search">⌕<span>搜索</span></Link><Link to="/favorites">♡<span>收藏</span></Link><Link to="/history">◷<span>历史</span></Link><Link to="/profile">○<span>我的</span></Link></nav></>}

function Home({settings}:{settings:Settings}){const [sources,setSources]=useState<any[]>([]);const [selected,setSelected]=useState(()=>localStorage.getItem('tvbox.homeSource')||'');const [videos,setVideos]=useState<Video[]>([]);const [history,setHistory]=useState<any[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{let cancelled=false;Promise.all([api<any[]>('/library'),api<any[]>('/history')]).then(([s,h])=>{if(cancelled)return;setSources(s);setHistory(h);const saved=localStorage.getItem('tvbox.homeSource');const preferred=saved||settings.homeSource||'';setSelected(s.some(x=>x.key===preferred)?preferred:'')}).catch(()=>{});return()=>{cancelled=true}},[settings.homeSource]);useEffect(()=>{if(!selected){setVideos([]);setLoading(false);return}localStorage.setItem('tvbox.homeSource',selected);let cancelled=false;setLoading(true);api<any>(`/library/videos?page=1&pageSize=100&sourceKey=${encodeURIComponent(selected)}`).then(v=>{if(cancelled)return;const next=(v.items||[]).map((x:any)=>({...x,sourceName:x.source?.name||x.sourceKey}));setVideos(next);hydrateMissingCovers(next,setVideos)}).catch(()=>{if(!cancelled)setVideos([])}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true}},[selected]);if(loading)return <HomeSkeleton/>;const visible=videos;const hero=visible[0];const watching=history.filter(x=>x.sourceKey===selected&&x.duration>0&&x.progress/x.duration<.95).slice(0,8).map(x=>({...x,id:x.videoId,sourceKey:x.sourceKey}));const progress=Object.fromEntries(history.map(x=>[x.videoId,x.duration?x.progress/x.duration*100:0]));const groups=[...new Set(visible.map(x=>x.category).filter((x):x is string=>Boolean(x)))].slice(0,5);const heroBackground=hero?.cover?`linear-gradient(90deg,rgba(8,8,10,.98),rgba(8,8,10,.60) 52%,rgba(8,8,10,.12)),url("${hero.cover}")`:'linear-gradient(90deg,rgba(8,8,10,.98),rgba(8,8,10,.60) 52%,rgba(8,8,10,.12))';return <div className="home-page">{settings.noticeEnabled!=='false'&&settings.noticeText&&<div className="announcement"><span>公告</span><div>{settings.noticeText}</div></div>}{settings.heroEnabled!=='false'&&hero&&<section className="hero-banner" style={{backgroundImage:heroBackground}}><div className="hero-copy"><small>首页数据源 · {hero.sourceName||hero.sourceKey}</small><h1>{hero.title}</h1><p>{hero.desc||`${hero.year||''} ${hero.category||''} ${hero.area||''}`}</p><div><Link className="play-button" to={`/detail/${hero.sourceKey}/${hero.id}`}>▶ 立即播放</Link><Link className="info-button" to={`/detail/${hero.sourceKey}/${hero.id}`}>ⓘ 详情</Link></div></div></section>}<div className="home-content"><div className="source-switch"><b>首页数据源</b>{sources.map(s=><button className={selected===s.key?'active':''} onClick={()=>setSelected(s.key)} key={s.key}>{s.name}</button>)}</div>{selected?<><Rail title="继续观看" items={watching} progress={progress}/><Rail title="资源列表" items={visible.slice(0,12)}/>{groups.map(group=><Rail key={group} title={group} items={visible.filter(x=>x.category===group).slice(0,12)}/>)}</>:<Empty title="请选择首页数据源" detail="选择一个数据源后，首页只加载该源内容。"/>}</div></div>}
function Sources(){const [items,setItems]=useState<any[]>();useEffect(()=>{api<any[]>('/library').then(setItems)},[]);if(!items)return <Spinner/>;return <Page title="片库" eyebrow="LIBRARY"><div className="library-note">本地采集内容和已配置的远程 TVBox 播放源都会显示在这里；远程源打开后实时读取内容。</div><div className="source-grid">{items.map(x=><Link className="source-tile" to={`/source/${x.key}`} key={x.key}><span>◈</span><div><h3>{x.name}</h3><p>{x.type==='local'?'本地资源': '远程资源'} · {x._count?.videos||0} 部已采集</p></div><b>→</b></Link>)}</div></Page>}
function Source(){const {key}=useParams();const [items,setItems]=useState<Video[]>([]);const [cats,setCats]=useState<string[]>([]);const [filters,setFilters]=useState<any>({years:[],areas:[],languages:[]});const [category,setCategory]=useState('');const [year,setYear]=useState('');const [area,setArea]=useState('');const [language,setLanguage]=useState('');const [page,setPage]=useState(1);const [total,setTotal]=useState(0);const [loading,setLoading]=useState(true);useEffect(()=>{Promise.all([api<string[]>(`/sources/${key}/categories`),api(`/sources/${key}/filters`)]).then(([c,f])=>{setCats(c);setFilters(f)})},[key]);useEffect(()=>{setLoading(true);const q=new URLSearchParams({page:String(page),pageSize:'40'});if(category)q.set('category',category);if(year)q.set('year',year);if(area)q.set('area',area);if(language)q.set('language',language);api<any>(`/sources/${key}/videos?${q}`).then(x=>{setItems(x.items);setTotal(x.total);hydrateMissingCovers(x.items,setItems)}).finally(()=>setLoading(false))},[key,page,category,year,area,language]);return <Page title="内容库" eyebrow={String(key||'SOURCE')}><div className="filter-bar"><select value={category} onChange={e=>{setCategory(e.target.value);setPage(1)}}><option value="">全部类型</option>{cats.map(x=><option key={x}>{x}</option>)}</select><select value={year} onChange={e=>setYear(e.target.value)}><option value="">全部年份</option>{filters.years.map((x:any)=><option key={x}>{x}</option>)}</select><select value={area} onChange={e=>setArea(e.target.value)}><option value="">全部地区</option>{filters.areas.map((x:any)=><option key={x}>{x}</option>)}</select><select value={language} onChange={e=>setLanguage(e.target.value)}><option value="">全部语言</option>{filters.languages.map((x:any)=><option key={x}>{x}</option>)}</select></div>{loading?<Spinner label="正在读取远程内容"/>:items.length?<><div className="movie-grid">{items.map(v=><MovieCard video={v} key={v.id}/>)}</div><Pager page={page} total={total} size={40} onChange={setPage}/></>:<Empty title="这个分类暂时没有内容"/>}</Page>}
function Pager({page,total,size,onChange}:{page:number;total:number;size:number;onChange:(n:number)=>void}){const pages=Math.max(1,Math.ceil(total/size));return <div className="pager"><button disabled={page===1} onClick={()=>onChange(page-1)}>← 上一页</button><span>{page} / {pages}</span><button disabled={page>=pages} onClick={()=>onChange(page+1)}>下一页 →</button></div>}
function Detail(){const {sourceKey,videoId}=useParams();const [video,setVideo]=useState<Video>();const [favorite,setFavorite]=useState(false);const [line,setLine]=useState('');const [reverse,setReverse]=useState(false);useEffect(()=>{performance.mark('detail-request-start');api<Video>(`/sources/${sourceKey}/videos/${videoId}`).then(v=>{setVideo(v);setLine(v.episodes?.[0]?.lineName||'默认线路');performance.mark('detail-request-end');if(import.meta.env.DEV)console.info('[大彪TV performance] detailFetchTime',performance.measure('detail-fetch','detail-request-start','detail-request-end').duration.toFixed(1)+'ms');const url=v.episodes?.[0]?.url;try{if(url){const origin=new URL(url).origin;if(!document.querySelector(`link[data-media-origin="${origin}"]`)){const link=document.createElement('link');link.rel='preconnect';link.href=origin;link.crossOrigin='anonymous';link.dataset.mediaOrigin=origin;document.head.appendChild(link)}}}catch{}});api<any[]>('/favorites').then(xs=>setFavorite(xs.some(x=>x.videoId===videoId)))},[sourceKey,videoId]);if(!video)return <Spinner label="正在读取影片详情"/>;const lines=[...new Set((video.episodes||[]).map(x=>x.lineName||'默认线路'))];const episodes=(video.episodes||[]).filter(x=>(x.lineName||'默认线路')===line).sort((a,b)=>reverse?b.sortOrder-a.sortOrder:a.sortOrder-b.sortOrder);const toggle=async()=>{if(favorite){const xs=await api<any[]>('/favorites');const row=xs.find(x=>x.videoId===videoId);if(row)await api(`/favorites/${row.id}`,{method:'DELETE'});setFavorite(false)}else{await api('/favorites',json({sourceKey,videoId,title:video.title,cover:video.cover}));setFavorite(true)}};return <div className="detail-page"><div className="detail-backdrop" style={{backgroundImage:`linear-gradient(90deg,#0b0b0f 5%,rgba(11,11,15,.82) 48%,rgba(11,11,15,.36)),url(${video.cover})`}}/><Link className="back-link" to={`/source/${sourceKey}`}>← 返回片库</Link><div className="detail-content"><div className="detail-poster"><Poster src={video.cover} title={video.title}/></div><div className="detail-info"><small>{video.category} · {video.year||'年份未知'} · {video.area||'地区未知'}</small><h1>{video.title}</h1><p>{video.desc||'暂无剧情简介'}</p><div className="detail-meta"><span><b>导演</b>{video.director||'未知'}</span><span><b>主演</b>{video.actors||'未知'}</span><span><b>语言</b>{video.language||'未知'}</span></div><div className="detail-actions">{episodes[0]&&<Link className="play-button" to={`/player/${sourceKey}/${videoId}/${episodes[0].id}`}>▶ 立即播放</Link>}<button className="info-button" onClick={toggle}>{favorite?'♥ 已收藏':'♡ 加入收藏'}</button></div><div className="episode-panel"><div className="episode-heading"><h2>选集</h2><button onClick={()=>setReverse(!reverse)}>{reverse?'倒序':'正序'} ↕</button></div><div className="line-tabs">{lines.map(x=><button className={line===x?'active':''} onClick={()=>setLine(x)} key={x}>{lineLabel(x)}</button>)}</div><div className="episode-grid">{episodes.map(e=><Link to={`/player/${sourceKey}/${videoId}/${e.id}`} key={e.id}>{e.name}</Link>)}</div></div></div></div></div>}

function DanmakuLayer({items,current}:{items:any[];current:number}){return <div className="danmaku-layer">{items.filter(x=>Math.abs(x.videoTime-current)<6).slice(-18).map((x,i)=><span key={`${x.id}-${i}`} style={{top:`${8+(i%7)*11}%`,animationDelay:`${(i%5)*-.5}s`}}>{x.content}</span>)}</div>}
function Player({settings}:{settings:Settings}){const {sourceKey,videoId,episodeId}=useParams();const nav=useNavigate();const videoRef=useRef<HTMLVideoElement>(null);const [video,setVideo]=useState<Video>();const [episode,setEpisode]=useState<Episode>();const [line,setLine]=useState('');const [current,setCurrent]=useState(0);const [danmaku,setDanmaku]=useState<any[]>([]);const [danmakuOn,setDanmakuOn]=useState(()=>localStorage.getItem('danmaku')!=='off');const [text,setText]=useState('');const [stage,setStage]=useState('正在获取播放线路…');const playStarted=useRef(performance.now());useEffect(()=>{api<Video>(`/sources/${sourceKey}/videos/${videoId}`).then(v=>{setVideo(v);const e=v.episodes?.find(x=>x.id===episodeId);setEpisode(e);setLine(e?.lineName||'');setStage('正在连接视频源…');if(import.meta.env.DEV)console.info('[大彪TV performance] playUrlResolveTime',(performance.now()-playStarted.current).toFixed(1)+'ms')})},[sourceKey,videoId,episodeId]);useEffect(()=>{if(episode)api<any[]>(`/danmaku?episodeId=${encodeURIComponent(episode.id)}`).then(setDanmaku)},[episode]);useEffect(()=>{const el=videoRef.current;if(!el||!episode)return;let h:Hls|undefined;if(episode.type==='m3u8'&&Hls.isSupported()){h=new Hls({manifestLoadingTimeOut:8000,levelLoadingTimeOut:8000,fragLoadingTimeOut:12000,maxBufferLength:30});h.loadSource(episode.url);h.attachMedia(el)}else el.src=episode.url;const playing=()=>{setStage('');if(import.meta.env.DEV)console.info('[大彪TV performance] playingTime',(performance.now()-playStarted.current).toFixed(1)+'ms')};const waiting=()=>setStage('正在缓冲视频…');const error=()=>{setStage('当前线路响应较慢，请尝试切换线路');api('/playback-errors',json({sourceKey,videoId,episodeId,errorType:'media',errorMessage:el.error?.message||'播放失败'})).catch(()=>{})};el.addEventListener('playing',playing);el.addEventListener('canplay',playing);el.addEventListener('waiting',waiting);el.addEventListener('error',error);return()=>{h?.destroy();el.removeEventListener('playing',playing);el.removeEventListener('canplay',playing);el.removeEventListener('waiting',waiting);el.removeEventListener('error',error)}},[episode]);const save=()=>{const el=videoRef.current;if(!el||!video||!episode||!Number.isFinite(el.duration))return;api('/history',json({sourceKey,videoId,episodeId,title:video.title,cover:video.cover,episodeName:episode.name,progress:el.currentTime,duration:el.duration,completed:el.currentTime/el.duration>.92})).catch(()=>{})};useEffect(()=>{const timer=setInterval(save,20000);const leave=()=>save();addEventListener('beforeunload',leave);return()=>{clearInterval(timer);removeEventListener('beforeunload',leave);save()}},[video,episode]);const all=video?.episodes||[];const lines=[...new Set(all.map(x=>x.lineName))];const episodes=all.filter(x=>x.lineName===line).sort((a,b)=>a.sortOrder-b.sortOrder);const index=episodes.findIndex(x=>x.id===episodeId);const switchLine=(next:string)=>{const target=all.find(x=>x.lineName===next);if(target)nav(`/player/${sourceKey}/${videoId}/${target.id}`)};const send=async()=>{if(!text.trim()||!episode)return;const row=await api('/danmaku',json({sourceKey,videoId,episodeId:episode.id,content:text,videoTime:videoRef.current?.currentTime||0}));setDanmaku([...danmaku,row]);setText('')};return <div className="watch-page"><div className="watch-top"><Link to={`/detail/${sourceKey}/${videoId}`}>← 返回详情</Link><span>{video?.title} {episode?.name&&`· ${episode.name}`}</span></div><div className="video-shell"><video ref={videoRef} controls autoPlay playsInline preload="metadata" onTimeUpdate={e=>setCurrent(e.currentTarget.currentTime)} onPause={save}/>{stage&&<div className="player-loading"><img src="/images/dabiao-icon.svg" alt="大彪TV"/><b>{stage}</b><small>{stage.includes('较慢')?'请选择下方其他线路':'正在优化首次播放连接'}</small></div>}{danmakuOn&&settings.danmakuEnabled!=='false'&&<DanmakuLayer items={danmaku.filter(x=>!x.simulated||settings.simulatedDanmakuEnabled!=='false')} current={current}/>}</div><div className="watch-toolbar"><div className="line-tabs"><b>播放线路</b>{lines.map(x=><button className={line===x?'active':''} onClick={()=>switchLine(x)} key={x}>{lineLabel(x)}</button>)}</div><button onClick={()=>{const n=!danmakuOn;setDanmakuOn(n);localStorage.setItem('danmaku',n?'on':'off')}}>{danmakuOn?'弹幕开':'弹幕关'}</button></div>{danmakuOn&&settings.realDanmakuEnabled!=='false'&&<div className="danmaku-send"><input value={text} maxLength={80} onChange={e=>setText(e.target.value)} onKeyDown={e=>e.key==='Enter'&&send()} placeholder="发一条友善的弹幕"/><button onClick={send}>发送</button></div>}<div className="watch-info"><div><h2>{video?.title||'正在加载'}</h2><p>{video?.desc||'暂无简介'}</p></div><div className="episode-nav">{episodes[index-1]?<Link to={`/player/${sourceKey}/${videoId}/${episodes[index-1].id}`}>← 上一集</Link>:<span/>}{episodes[index+1]&&<Link to={`/player/${sourceKey}/${videoId}/${episodes[index+1].id}`}>下一集 →</Link>}</div></div><div className="episode-grid player-episode-grid">{episodes.map(x=><Link className={x.id===episodeId?'active':''} to={`/player/${sourceKey}/${videoId}/${x.id}`} key={x.id}>{x.name}</Link>)}</div></div>}

const categoryMatches=(value:string|undefined,category:string)=>{const text=String(value||'');if(category==='动漫')return /动漫|动画|番剧|里番/.test(text);if(category==='电视剧')return /剧|电视剧/.test(text)&&!/综艺/.test(text);return /电影|片/.test(text)&&!/动漫|动画/.test(text)};
function CategoryBrowse({category}:{category:string}){const [sources,setSources]=useState<any[]>([]);const [selected,setSelected]=useState(()=>localStorage.getItem('tvbox.homeSource')||'');const [items,setItems]=useState<Video[]>([]);const [loading,setLoading]=useState(true);useEffect(()=>{api<any[]>('/library').then(s=>{setSources(s);const saved=localStorage.getItem('tvbox.homeSource');setSelected(s.some(x=>x.key===saved)?saved:(s[0]?.key||''))}).catch(()=>{setSources([]);setLoading(false)})},[]);useEffect(()=>{if(!selected){setItems([]);setLoading(false);return}let cancelled=false;setLoading(true);Promise.all([1,2,3].map(page=>api<any>(`/sources/${selected}/videos?page=${page}&pageSize=100`))).then(results=>{if(cancelled)return;const seen=new Set<string>();const next=results.flatMap(x=>x.items||[]).filter((x:any)=>categoryMatches(x.category,category)&&!seen.has(x.id)&&(seen.add(x.id),true));setItems(next);hydrateMissingCovers(next,setItems)}).catch(()=>{if(!cancelled)setItems([])}).finally(()=>{if(!cancelled)setLoading(false)});return()=>{cancelled=true}},[selected,category]);return <Page title={category} eyebrow="CATEGORY"><div className="source-switch"><b>当前数据源</b>{sources.map(s=><button className={selected===s.key?'active':''} onClick={()=>{localStorage.setItem('tvbox.homeSource',s.key);setSelected(s.key)}} key={s.key}>{s.name}</button>)}</div>{loading?<Spinner label="正在读取分类资源"/>:items.length?<div className="movie-grid">{items.map(v=><MovieCard video={v} key={v.id}/>)}</div>:<Empty title={`当前源没有${category}资源`} detail="请切换上方数据源，或使用搜索页查找关键词"/>}</Page>}
function Search(){const location=useLocation();const nav=useNavigate();const initial=new URLSearchParams(location.search).get('q')||'';const [query,setQuery]=useState(initial);const [items,setItems]=useState<Video[]>();useEffect(()=>{if(initial&&!['电影','电视剧','动漫'].includes(initial))api<Video[]>('/search?q='+encodeURIComponent(initial)).then(next=>{setItems(next);hydrateMissingCovers(next,setItems)});else if(!['电影','电视剧','动漫'].includes(initial))setItems([])},[initial]);if(['电影','电视剧','动漫'].includes(initial))return <CategoryBrowse category={initial}/>;return <Page title="搜索" eyebrow="DISCOVER"><form className="big-search" onSubmit={e=>{e.preventDefault();nav('/search?q='+encodeURIComponent(query.trim()))}}><span>⌕</span><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="搜索影视名称、演员、导演或类型"/><button>搜索</button></form>{items===undefined?<Spinner/>:items.length?<div className="movie-grid">{items.map(v=><MovieCard video={v} key={v.id}/>)}</div>:<Empty title={initial?'没有找到相关内容':'输入关键词开始搜索'} detail={initial?'换个片名、演员或导演试试':''}/>}</Page>}
function Favorites(){const [items,setItems]=useState<any[]>();const load=()=>api<any[]>('/favorites').then(setItems);useEffect(()=>{void load()},[]);return <Page title="我的收藏" eyebrow="MY LIST">{items===undefined?<Spinner/>:items.length?<div className="movie-grid">{items.map(x=><div className="library-item" key={x.id}><MovieCard video={{...x,id:x.videoId}}/><button onClick={async()=>{await api(`/favorites/${x.id}`,{method:'DELETE'});load()}}>移除</button></div>)}</div>:<Empty title="收藏夹还是空的" detail="在影片详情页点击加入收藏"/>}</Page>}
function History(){const [items,setItems]=useState<any[]>();const [confirmClear,setConfirmClear]=useState(false);const load=()=>api<any[]>('/history').then(setItems);useEffect(()=>{void load()},[]);return <Page title="观看历史" eyebrow="WATCH HISTORY"><div className="page-actions">{!!items?.length&&<button onClick={()=>setConfirmClear(true)}>清空历史</button>}</div>{items===undefined?<Spinner/>:items.length?<div className="history-list">{items.map(x=><div key={x.id}><Link to={`/player/${x.sourceKey}/${x.videoId}/${x.episodeId}`}><div className="history-cover"><Poster src={x.cover} title={x.title}/></div><div><h3>{x.title}</h3><p>{x.episodeName||'继续观看'} · {timeAgo(x.updatedAt)}</p><Progress value={x.duration?x.progress/x.duration*100:0}/></div></Link><button onClick={async()=>{await api(`/history/${x.id}`,{method:'DELETE'});load()}}>×</button></div>)}</div>:<Empty title="暂无观看记录"/>}{confirmClear&&<div className="modal-backdrop" onClick={()=>setConfirmClear(false)}><div className="confirm-dialog" onClick={e=>e.stopPropagation()}><h3>清空观看历史？</h3><p>这会删除你的全部观看记录，且无法撤销。</p><div><button onClick={()=>setConfirmClear(false)}>取消</button><button className="danger-action" onClick={async()=>{await api('/history',{method:'DELETE'});setConfirmClear(false);load()}}>确认清空</button></div></div></div>}</Page>}
function Profile({user}:{user:User}){const tab=new URLSearchParams(useLocation().search).get('tab')||'profile';const [profile,setProfile]=useState<any>();const [form,setForm]=useState({displayName:'',avatarUrl:''});const [password,setPassword]=useState({currentPassword:'',newPassword:''});const [message,setMessage]=useState('');useEffect(()=>{api('/profile').then(x=>{setProfile(x);setForm({displayName:x.displayName,avatarUrl:x.avatarUrl})})},[]);if(!profile)return <Spinner/>;return <div className="profile-layout"><aside><Avatar user={{...user,...form}} large/><h2>{form.displayName||user.username}</h2><p>{user.role==='admin'?'管理员':'普通用户'}</p><Link className={tab==='profile'?'active':''} to="/profile">个人资料</Link><Link className={tab==='continue'?'active':''} to="/profile?tab=continue">继续观看</Link><Link to="/history">观看历史</Link><Link to="/favorites">我的收藏</Link><Link className={tab==='account'?'active':''} to="/profile?tab=account">账号设置</Link></aside><main>{tab==='continue'?<><h1>继续观看</h1><div className="history-list">{profile.recent.map((x:any)=><div key={x.id}><Link to={`/player/${x.sourceKey}/${x.videoId}/${x.episodeId}`}><div className="history-cover"><Poster src={x.cover} title={x.title}/></div><div><h3>{x.title}</h3><p>{x.episodeName}</p><Progress value={x.duration?x.progress/x.duration*100:0}/></div></Link></div>)}</div></>:tab==='account'?<><h1>账号设置</h1><div className="profile-form"><label>当前密码<input type="password" value={password.currentPassword} onChange={e=>setPassword({...password,currentPassword:e.target.value})}/></label><label>新密码<input type="password" value={password.newPassword} onChange={e=>setPassword({...password,newPassword:e.target.value})}/></label><button className="primary" onClick={async()=>{await api('/profile/password',json(password));setMessage('密码修改成功');setPassword({currentPassword:'',newPassword:''})}}>修改密码</button></div></>:<><h1>个人资料</h1><div className="profile-stats"><span><b>{profile.stats.historyCount}</b>观看记录</span><span><b>{profile.stats.favorites}</b>收藏</span><span><b>{Math.round(profile.stats.watchSeconds/3600)}</b>观看小时</span></div><div className="profile-form"><label>用户名<input value={profile.username} disabled/></label><label>昵称<input value={form.displayName} onChange={e=>setForm({...form,displayName:e.target.value})}/></label><label>头像地址<input value={form.avatarUrl} onChange={e=>setForm({...form,avatarUrl:e.target.value})}/></label><button className="primary" onClick={async()=>{await api('/profile',{...json(form),method:'PUT'});setMessage('个人资料已保存')}}>保存资料</button></div></>}{message&&<p className="success-message">{message}</p>}</main></div>}

const adminLinks=[['/admin','仪表盘','▦'],['/admin/settings','网站设置','⚙'],['/admin/sources','数据源管理','◉'],['/admin/collection','本地采集','⇩'],['/admin/categories','分类管理','#'],['/admin/videos','视频管理','▤'],['/admin/editor','源配置','⌘'],['/admin/users','用户管理','♙'],['/admin/history','观看统计','◷'],['/admin/danmaku','弹幕管理','≋'],['/admin/errors','播放错误','!'],['/admin/logs','系统日志','☰']];
function CategoryManager(){const [items,setItems]=useState<any[]>(),[name,setName]=useState(''),[message,setMessage]=useState('');const load=()=>api<any[]>('/admin/category-stats').then(setItems);useEffect(()=>{void load()},[]);const add=async()=>{const n=name.trim();if(!n)return;const all=(items||[]).map(x=>x.name);await api('/admin/categories',json({categories:[...new Set([...all,n])]}));setName('');setMessage('分类已添加');load()};const rename=async(old:string)=>{const n=window.prompt('修改分类名称',old)?.trim();if(n&&n!==old){await api(`/admin/categories/${encodeURIComponent(old)}`,{...json({name:n}),method:'PUT'});setMessage('分类已修改');load()}};const remove=async(old:string)=>{if(!window.confirm(`确定删除“${old}”？视频将移到未分类`))return;await api(`/admin/categories/${encodeURIComponent(old)}`,{method:'DELETE',headers:{'Content-Type':'application/json'},body:'{}'});setMessage('分类已删除');load()};return <AdminFrame title="分类管理"><div className="manager-intro"><b>本站分类</b><p>统一管理分类名称，修改后会同步更新绑定和本地视频。</p></div><div className="manager-add"><input value={name} onChange={e=>setName(e.target.value)} placeholder="输入新分类名称"/><button className="primary" onClick={()=>void add()}>添加分类</button></div>{message&&<p className="success-message">{message}</p>}<div className="category-grid">{!items?<Spinner/>:items.map(x=><div className="category-card" key={x.name}><div><b>{x.name}</b><small>{x.videoCount} 部本地视频</small></div><span><button onClick={()=>void rename(x.name)}>改名</button><button className="danger-text" onClick={()=>void remove(x.name)}>删除</button></span></div>)}</div></AdminFrame>}
function VideoManager(){const [items,setItems]=useState<any[]>(),[sources,setSources]=useState<any[]>([]),[categories,setCategories]=useState<any[]>([]),[selected,setSelected]=useState<string[]>([]),[q,setQ]=useState(''),[sourceKey,setSourceKey]=useState(''),[category,setCategory]=useState(''),[message,setMessage]=useState('');const load=()=>api<any>(`/admin/videos?page=1&pageSize=100&q=${encodeURIComponent(q)}&sourceKey=${encodeURIComponent(sourceKey)}&category=${encodeURIComponent(category)}`).then(x=>{setItems(x.items);setSelected([])});useEffect(()=>{void load();api<any[]>('/admin/sources').then(setSources);api<any[]>('/admin/category-stats').then(setCategories)},[]);const bulk=async(action:string)=>{if(!selected.length)return setMessage('请先选择视频');if(action==='delete'&&!window.confirm('确定删除选中的本地视频？'))return;await api('/admin/videos/batch',json({ids:selected,action,category}));setMessage('批量操作已完成');load()};return <AdminFrame title="视频管理"><div className="manager-intro"><b>本地视频库</b><p>只管理已采集到本机的内容，可批量显示、隐藏、推荐、改分类或删除。</p></div><div className="video-filters"><input placeholder="搜索视频名称" value={q} onChange={e=>setQ(e.target.value)} onKeyDown={e=>e.key==='Enter'&&void load()}/><select value={sourceKey} onChange={e=>setSourceKey(e.target.value)}><option value="">全部数据源</option>{sources.map(x=><option key={x.key} value={x.key}>{x.name}</option>)}</select><select value={category} onChange={e=>setCategory(e.target.value)}><option value="">全部分类</option>{categories.map(x=><option key={x.name} value={x.name}>{x.name}</option>)}</select><button onClick={()=>void load()}>筛选</button></div><div className="video-bulk"><label><input type="checkbox" checked={Boolean(items?.length&&selected.length===items.length)} onChange={e=>setSelected(e.target.checked?(items||[]).map(x=>x.id):[])}/> 全选</label><button onClick={()=>void bulk('show')}>批量显示</button><button onClick={()=>void bulk('hide')}>批量隐藏</button><button onClick={()=>void bulk('feature')}>设为推荐</button><button onClick={()=>void bulk('unfeature')}>取消推荐</button><select onChange={e=>{setCategory(e.target.value);if(e.target.value)void bulk('category')}} value=""><option value="">批量改分类</option>{categories.map(x=><option key={x.name} value={x.name}>{x.name}</option>)}</select><button className="danger-text" onClick={()=>void bulk('delete')}>批量删除</button></div>{message&&<p className="success-message">{message}</p>}{!items?<Spinner/>:<div className="video-table"><div className="video-table-head"><span></span><span>视频</span><span>数据源</span><span>分类</span><span>状态</span></div>{items.map(x=><div className="video-table-row" key={x.id}><input type="checkbox" checked={selected.includes(x.id)} onChange={e=>setSelected(e.target.checked?[...selected,x.id]:selected.filter(id=>id!==x.id))}/><span className="video-title"><img src={x.cover||'/images/dabiao-icon.svg'}/><b>{x.title}</b></span><span>{x.source?.name||x.sourceKey}</span><span>{x.category||'未分类'}</span><span>{x.visible===false?'已隐藏':'显示中'}{x.featured?' · 推荐':''}</span></div>)}</div>}</AdminFrame>}
function SchedulePanel(){const [cfg,setCfg]=useState<any>({enabled:false,intervalMinutes:1440,nextAt:null}),[message,setMessage]=useState('');useEffect(()=>{api('/admin/collection-schedule').then(setCfg)},[]);const save=async()=>{const x=await api('/admin/collection-schedule',{...json(cfg),method:'PUT'});setCfg(x);setMessage('自动采集间隔已保存')};const mins=Number(cfg.intervalMinutes)||1440;const label=mins<60?`每 ${mins} 分钟`:mins%60?`每 ${Math.floor(mins/60)} 小时 ${mins%60} 分钟`:`每 ${mins/60} 小时`;return <section className="schedule-panel"><div><b>自动采集间隔</b><p>按已保存的分类绑定，自动采集所有启用数据源。</p></div><label><input type="checkbox" checked={cfg.enabled} onChange={e=>setCfg({...cfg,enabled:e.target.checked})}/> 开启</label><select value={cfg.intervalMinutes} onChange={e=>setCfg({...cfg,intervalMinutes:Number(e.target.value)})}><option value="30">每 30 分钟</option><option value="60">每 1 小时</option><option value="180">每 3 小时</option><option value="360">每 6 小时</option><option value="720">每 12 小时</option><option value="1440">每 24 小时</option><option value="2880">每 2 天</option><option value="10080">每 7 天</option></select><button onClick={()=>void save()}>保存</button><small>{cfg.enabled?(cfg.nextAt?`下一次采集：${new Date(cfg.nextAt).toLocaleString()}（${label}）`:`已开启（${label}）`):'自动采集未开启'}</small>{message&&<small>{message}</small>}</section>}
function AdminFrame({title,children}:{title:string;children:React.ReactNode}){const location=useLocation();return <div className="admin-shell"><aside className="admin-sidebar"><Link className="admin-brand" to="/admin"><img src="/images/dabiao-logo.svg" alt="大彪TV"/><small>管理后台</small></Link><nav>{adminLinks.map(([href,label,icon])=><Link className={location.pathname===href?'active':''} to={href} key={href}><i>{icon}</i>{label}</Link>)}</nav><Link className="back-site" to="/">← 返回网站</Link></aside><section className="admin-workspace"><header><div><small>DABIAO CONSOLE</small><h1>{title}</h1></div><span>{new Date().toLocaleDateString()}</span></header>{children}</section></div>}
function AdminDashboard(){const [data,setData]=useState<any>();useEffect(()=>{api('/admin/dashboard').then(setData)},[]);if(!data)return <AdminFrame title="仪表盘"><Spinner/></AdminFrame>;const max=Math.max(1,...data.trend.map((x:any)=>x.count));return <AdminFrame title="仪表盘"><div className="admin-stats">{[['平台用户',data.users],['今日新增',data.newUsers],['今日活跃',data.activeUsers],['今日播放',data.todayPlays],['总观看记录',data.historyTotal],['有效数据源',`${data.healthy}/${data.sources}`],['今日播放错误',data.errors]].map(([a,b])=><div key={String(a)}><span>{a}</span><b>{b}</b></div>)}</div><div className="dashboard-grid"><article className="chart-card"><h3>最近 7 天播放趋势</h3><div className="bar-chart">{data.trend.map((x:any)=><div key={x.date}><i style={{height:`${Math.max(5,x.count/max*100)}%`}}/><span>{x.date.slice(5)}</span><b>{x.count}</b></div>)}</div></article><article><h3>热门搜索</h3><ol>{data.topSearches.map((x:any)=><li key={x.keyword}><span>{x.keyword}</span><b>{x._count.keyword}</b></li>)}</ol></article><article><h3>收藏最多</h3><ol>{data.topFavorites.map((x:any)=><li key={x.title}><span>{x.title}</span><b>{x._count.title}</b></li>)}</ol></article><article><h3>最近用户</h3><ol>{data.recentUsers.map((x:any)=><li key={x.id}><span>{x.displayName||x.username}</span><small>{timeAgo(x.createdAt)}</small></li>)}</ol></article></div></AdminFrame>}
function AdminSettings(){const defaults={siteName:'',logoUrl:'',faviconUrl:'',siteDescription:'',seoTitle:'',seoDescription:'',footerText:'',copyrightText:'',noticeText:'',noticeEnabled:'true',themePreset:'netflix',accentColor:'#e50914',cardRadius:'8',headerOpacity:'88',heroEnabled:'true',homeSource:'',danmakuEnabled:'true',realDanmakuEnabled:'true',simulatedDanmakuEnabled:'true',simulatedDanmakuDensity:'medium',lineAliases:'{}'};const [form,setForm]=useState<any>(defaults);const [sources,setSources]=useState<any[]>([]);const [saved,setSaved]=useState(false);useEffect(()=>{api('/settings').then(x=>setForm({...defaults,...x}));api<any[]>('/admin/sources').then(setSources)},[]);const field=(key:string,label:string,type='text')=><label>{label}<input type={type} value={form[key]} onChange={e=>setForm({...form,[key]:e.target.value})}/></label>;const toggle=(key:string,label:string)=><label className="toggle"><input type="checkbox" checked={form[key]!=='false'} onChange={e=>setForm({...form,[key]:String(e.target.checked)})}/><span/>{label}</label>;return <AdminFrame title="网站设置"><div className="settings-sections"><section><h2>品牌与 SEO</h2><div className="admin-form">{field('siteName','网站名称')}{field('logoUrl','Logo 地址')}{field('faviconUrl','Favicon 地址')}{field('siteDescription','网站描述')}{field('seoTitle','SEO 标题')}{field('seoDescription','SEO 描述')}{field('footerText','页脚内容')}{field('copyrightText','版权信息')}</div></section><section><h2>首页内容</h2><div className="admin-form full"><label>默认首页数据源<select value={form.homeSource||''} onChange={e=>setForm({...form,homeSource:e.target.value})}><option value="">首次进入时由用户选择</option>{sources.map(x=><option key={x.key} value={x.key}>{x.name}</option>)}</select></label><p>首页也可以直接点击“首页数据源”切换；这里用于没有选择记录的浏览器。</p></div></section><section><h2>首页公告</h2><div className="admin-form full">{field('noticeText','公告内容')}{toggle('noticeEnabled','显示公告')}{toggle('heroEnabled','显示 Hero Banner')}</div></section><section><h2>主题</h2><div className="admin-form"><label>主题预设<select value={form.themePreset} onChange={e=>setForm({...form,themePreset:e.target.value})}><option value="netflix">Netflix</option><option value="dark">Pure Dark</option><option value="cinema">Cinema</option><option value="compact">Compact</option></select></label>{field('accentColor','强调色','color')}{field('cardRadius','卡片圆角')}{field('headerOpacity','顶部透明度')}</div></section><section><h2>播放与弹幕</h2><div className="admin-form full">{toggle('danmakuEnabled','弹幕总开关')}{toggle('realDanmakuEnabled','真实弹幕')}{toggle('simulatedDanmakuEnabled','模拟弹幕')}<label>模拟弹幕密度<select value={form.simulatedDanmakuDensity} onChange={e=>setForm({...form,simulatedDanmakuDensity:e.target.value})}><option value="low">低</option><option value="medium">中</option><option value="high">高</option></select></label><label>播放器名称映射<input value={form.lineAliases} onChange={e=>setForm({...form,lineAliases:e.target.value})}/></label></div></section><button className="primary" onClick={async()=>{await api('/settings',json(form));localStorage.setItem('tvbox.lineAliases',form.lineAliases);setSaved(true)}}>保存全部设置</button>{saved&&<span className="success-message">保存成功，刷新前台后生效</span>}</div></AdminFrame>}
function AdminSources(){const [items,setItems]=useState<any[]>();const [busy,setBusy]=useState(false);const load=()=>api<any[]>('/admin/sources').then(setItems);useEffect(()=>{void load()},[]);const test=async(key:string)=>{setBusy(true);await api(`/admin/sources/${key}/refresh`,{method:'POST'}).catch(()=>{});await load();setBusy(false)};const toggleSearch=async(x:any)=>{setBusy(true);await api(`/admin/sources/${x.key}`,{...json({searchable:!x.searchable}),method:'PUT'});await load();setBusy(false)};return <AdminFrame title="数据源管理"><div className="admin-actions"><p>影视内容仍从远程源实时读取；可在每个源的操作中关闭搜索，关闭后该源不会出现在全站搜索结果。</p><button disabled={busy} onClick={async()=>{setBusy(true);await api('/admin/sources/test-all',{method:'POST'});await load();setBusy(false)}}>{busy?'检测中…':'批量检测全部源'}</button></div>{!items?<Spinner/>:<div className="admin-table"><div className="table-head"><span>数据源</span><span>状态</span><span>响应</span><span>成功率</span><span>最后检测</span><span>操作</span></div>{items.map(x=>{const total=x.successCount+x.failCount;const rate=total?Math.round(x.successCount/total*100):0;const state=!x.lastCheckedAt?'unknown':x.lastError?'bad':x.lastLatencyMs>3000?'slow':'good';return <div className="table-row" key={x.key}><span><b>{x.name}</b><small>{x.api}</small></span><span><i className={`status ${state}`}/>{state==='good'?'健康':state==='slow'?'较慢':state==='bad'?'异常':'未检测'}</span><span>{x.lastLatencyMs?`${x.lastLatencyMs}ms`:'—'}</span><span>{total?`${rate}%`:'—'}</span><span>{x.lastCheckedAt?timeAgo(x.lastCheckedAt):'—'}</span><span><button onClick={()=>test(x.key)}>测试</button><button disabled={busy} onClick={()=>void toggleSearch(x)}>{x.searchable?'关闭搜索':'开启搜索'}</button></span></div>})}</div>}</AdminFrame>}
function AdminUsers(){const [items,setItems]=useState<any[]>();const [sources,setSources]=useState<any[]>([]);const [form,setForm]=useState<any>({username:'',password:'',role:'user',pageAccess:'home,sources,search,favorites,history',sourceKeys:[]});const load=()=>api<any[]>('/admin/users').then(setItems);useEffect(()=>{load();api<any[]>('/sources').then(setSources)},[]);return <AdminFrame title="用户管理"><div className="create-user"><input placeholder="用户名" value={form.username} onChange={e=>setForm({...form,username:e.target.value})}/><input placeholder="初始密码" type="password" value={form.password} onChange={e=>setForm({...form,password:e.target.value})}/><select value={form.role} onChange={e=>setForm({...form,role:e.target.value})}><option value="user">普通用户</option><option value="admin">管理员</option></select><button onClick={async()=>{await api('/admin/users',json({...form,sourceKeys:form.role==='admin'?[]:sources.map(x=>x.key)}));setForm({...form,username:'',password:''});load()}}>创建用户</button></div>{!items?<Spinner/>:<div className="admin-table users-table"><div className="table-head"><span>用户</span><span>角色</span><span>页面权限</span><span>状态</span><span>操作</span></div>{items.map(x=><div className="table-row" key={x.id}><span><b>{x.username}</b><small>ID #{x.id}</small></span><span>{x.role==='admin'?'管理员':'普通用户'}</span><span>{x.pageAccess}</span><span><i className={`status ${x.enabled?'good':'bad'}`}/>{x.enabled?'正常':'禁用'}</span><span><button onClick={async()=>{await api(`/admin/users/${x.id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({...x,enabled:!x.enabled,sourceKeys:x.sourceAccess.map((s:any)=>s.sourceKey)})});load()}}>{x.enabled?'禁用':'启用'}</button></span></div>)}</div>}</AdminFrame>}
function CollectionCenter(){const [sources,setSources]=useState<any[]>([]);const [selected,setSelected]=useState('');const [categories,setCategories]=useState<string[]>([]);const [bindings,setBindings]=useState<any[]>([]);const [localCategories,setLocalCategories]=useState<string[]>([]);const [status,setStatus]=useState<any>();const [message,setMessage]=useState('');const [busy,setBusy]=useState(false);const loadSources=()=>api<any[]>('/admin/sources').then(x=>{setSources(x);setSelected(current=>current||x[0]?.key||'')});useEffect(()=>{void loadSources()},[]);useEffect(()=>{if(!selected)return;setMessage('');api<any>(`/admin/sources/${selected}/collection-info`).then(x=>{setCategories(x.categories);setBindings(x.bindings.map((b:any)=>({...b})));setLocalCategories(x.localCategories);setStatus(x.status)}).catch(e=>setMessage(e.message))},[selected]);useEffect(()=>{if(!selected)return;const timer=window.setInterval(()=>api<any>(`/admin/sources/${selected}/collection-status`).then(setStatus).catch(()=>{}),1000);return()=>clearInterval(timer)},[selected]);const bindingFor=(remoteCategory:string)=>bindings.find(x=>x.remoteCategory===remoteCategory);const setBinding=(remoteCategory:string,localCategory:string)=>setBindings(current=>[...current.filter(x=>x.remoteCategory!==remoteCategory),...(localCategory?[{remoteCategory,localCategory,enabled:true}]:[])]);const autoBind=()=>setBindings(categories.map(remoteCategory=>({remoteCategory,localCategory:guessCategory(remoteCategory,localCategories),enabled:true})).filter(x=>x.localCategory));const addCategory=async()=>{const name=window.prompt('请输入本站分类名称');if(!name?.trim())return;const next=[...new Set([...localCategories,name.trim()])];try{await api('/admin/categories',json({categories:next}));setLocalCategories(next);setMessage(`已添加分类：${name.trim()}`)}catch(e:any){setMessage(e.message)}};const save=async()=>{setBusy(true);try{await api(`/admin/sources/${selected}/category-bindings`,{...json({bindings}),method:'PUT'});setMessage('分类绑定已保存')}catch(e:any){setMessage(e.message)}finally{setBusy(false)}};const collect=async(mode:'incremental'|'all')=>{setBusy(true);try{const x=await api(`/admin/sources/${selected}/collect`,json({mode,limit:mode==='all'?0:500}));setMessage(x.message);setStatus((await api(`/admin/sources/${selected}/collection-status`)))}catch(e:any){setMessage(e.message)}finally{setBusy(false)}};return <AdminFrame title="本地采集"><div className="collection-intro"><b>远程源 → 分类绑定 → 本地内容库</b><p>绑定后才会入库。影片、封面、简介、播放线路和剧集保存到本机数据库，前台优先读取本地内容。</p></div><div className="collection-toolbar"><label>选择数据源<select value={selected} onChange={e=>setSelected(e.target.value)}>{sources.map(x=><option key={x.key} value={x.key}>{x.name}</option>)}</select></label><button onClick={autoBind} disabled={!categories.length}>自动绑定同名分类</button><button onClick={addCategory}>＋ 手动添加分类</button><button onClick={()=>void save()} disabled={busy||!selected}>保存分类绑定</button></div>{selected&&<section className="binding-panel"><div className="binding-head"><h2>采集分类绑定</h2><span>{categories.length} 个资源站分类 · {localCategories.length} 个本站分类</span></div>{!categories.length?<Spinner label="正在读取远程分类"/>:<div className="binding-list">{categories.map(remoteCategory=>{const row=bindingFor(remoteCategory);return <div className="binding-row" key={remoteCategory}><span>{remoteCategory}</span><b>→</b><select value={row?.localCategory||''} onChange={e=>setBinding(remoteCategory,e.target.value)}><option value="">不采集</option>{localCategories.map(x=><option key={x} value={x}>{x}</option>)}</select></div>})}</div>}</section>}{status&&<section className="collection-status"><div><small>本地已入库</small><strong>{status.collectedCount||0}</strong></div><div><small>采集状态</small><strong>{status.running||status.collectionStatus==='running'?'采集中…':status.collectionStatus==='error'?'失败':'空闲'}</strong>{status.progress&&<small>{status.progress.processed||0} / {status.progress.total||'…'} · 第 {status.progress.page||0} 页</small>}</div><div><small>上次采集</small><strong>{status.lastCollectedAt?timeAgo(status.lastCollectedAt):'尚未采集'}</strong></div></section>}<div className="collection-actions"><button className="primary" disabled={busy||!selected} onClick={()=>void collect('incremental')}>采集最近一页</button><button disabled={busy||!selected} onClick={()=>void collect('all')}>采集全部（不设数量上限）</button>{status?.running&&<button className="danger-text" onClick={async()=>{await api(`/admin/sources/${selected}/collect/cancel`,{method:'POST'});setMessage('已发送取消请求')}}>取消采集</button>}</div><SchedulePanel/>{message&&<p className="success-message">{message}</p>}</AdminFrame>}
function AdminList({kind,title}:{kind:'history'|'errors'|'logs';title:string}){const [items,setItems]=useState<any[]>();useEffect(()=>{api<any[]>(`/admin/${kind}`).then(setItems)},[kind]);return <AdminFrame title={title}>{!items?<Spinner/>:items.length?<div className="log-list">{items.map((x:any)=><div key={x.id}><i className={`status ${kind==='errors'?'bad':'good'}`}/><div><b>{x.title||x.action||x.errorType}</b><p>{x.username||x.sourceKey} · {x.episodeName||x.errorMessage||x.detail||'无详细信息'}</p></div><time>{timeAgo(x.updatedAt||x.createdAt)}</time></div>)}</div>:<Empty title="暂无记录"/>}</AdminFrame>}
function AdminDanmaku(){const [items,setItems]=useState<any[]>();const [words,setWords]=useState('');const load=()=>api<any[]>('/admin/danmaku').then(setItems);useEffect(()=>{void load()},[]);return <AdminFrame title="弹幕管理"><div className="simulated-box"><h3>模拟弹幕词库</h3><textarea value={words} onChange={e=>setWords(e.target.value)} placeholder="每行一条弹幕，可批量导入"/><button onClick={async()=>{await api('/admin/danmaku/simulated',json({content:words,episodeId:'global'}));setWords('');load()}}>批量导入</button></div>{!items?<Spinner/>:<div className="log-list">{items.map(x=><div key={x.id}><i className={`status ${x.enabled?'good':'bad'}`}/><div><b>{x.content}</b><p>{x.simulated?'模拟弹幕':'真实弹幕'} · {x.episodeId}</p></div><button onClick={async()=>{await api(`/admin/danmaku/${x.id}`,{method:'DELETE'});load()}}>删除</button></div>)}</div>}</AdminFrame>}
function SourceEditor(){const [config,setConfig]=useState<any>({name:'大彪TV',sites:[]});const [message,setMessage]=useState('');useEffect(()=>{api('/config').then(setConfig)},[]);const importLocal=async()=>{try{const result=await api<any>('/config/import-local',{method:'POST'});setMessage(`已从 tvbox.json 恢复 ${result.sites} 个播放源`);setConfig(await api('/config'))}catch(error:any){setMessage(error.message)}};return <AdminFrame title="源配置"><div className="source-editor"><label>配置名称<input value={config.name||''} onChange={e=>setConfig({...config,name:e.target.value})}/></label><div className="admin-actions"><p>数据库连接由启动时的 .env 中 DATABASE_URL 决定；下面的源配置保存到 SQLite。</p><button onClick={()=>void importLocal()}>从 tvbox.json 恢复</button></div>{config.sites.map((x:any,i:number)=><div className="source-edit-row" key={i}><input value={x.name} onChange={e=>setConfig({...config,sites:config.sites.map((s:any,n:number)=>n===i?{...s,name:e.target.value}:s)})}/><input value={x.api} onChange={e=>setConfig({...config,sites:config.sites.map((s:any,n:number)=>n===i?{...s,api:e.target.value}:s)})}/><button onClick={()=>setConfig({...config,sites:config.sites.filter((_:any,n:number)=>n!==i)})}>删除</button></div>)}<button onClick={()=>setConfig({...config,sites:[...config.sites,{key:`source_${Date.now()}`,name:'新数据源',type:'tvbox-json',api:'',searchable:1,quickSearch:1,filterable:1}]})}>＋ 添加数据源</button><button className="primary" onClick={async()=>{await api('/config',json({rawConfig:JSON.stringify(config)}));setMessage('数据源配置已保存')}}>保存配置</button>{message&&<span className="success-message">{message}</span>}</div></AdminFrame>}

export default function App(){const path=useLocation().pathname;const chrome=!path.startsWith('/admin')&&path!='/login'&&path!='/install';const [user,setUser]=useState<User|null|undefined>(undefined);const [installation,setInstallation]=useState<any>(null);const [settings,setSettings]=useState<Settings>({siteName:'大彪TV',logoUrl:'/images/dabiao-logo.svg',faviconUrl:'/images/dabiao-icon.svg'});useEffect(()=>{Promise.all([api<any>('/install/status'),api<User|null>('/auth/me'),api<Settings>('/settings')]).then(([status,u,s])=>{setInstallation(status);setUser(u);setSettings(s);if(s.lineAliases)localStorage.setItem('tvbox.lineAliases',s.lineAliases);document.documentElement.style.setProperty('--accent',s.accentColor||'#e50914');document.documentElement.style.setProperty('--radius',`${s.cardRadius||8}px`);document.title=s.seoTitle||s.siteName||'大彪TV';document.documentElement.dataset.theme=s.themePreset||'netflix';if(s.faviconUrl){let link=document.querySelector("link[rel='icon']") as HTMLLinkElement|null;if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link)}link.href=s.faviconUrl}}).catch(()=>{setInstallation({installed:false});setUser(null)})},[]);if(!installation)return <Spinner label="正在检查安装状态"/>;if(!installation.installed)return <Install settings={settings} status={installation}/>;const logout=async()=>{await api('/auth/logout',{method:'POST'});setUser(null)};return <>{chrome&&<Header user={user||null} settings={settings} onLogout={logout}/>}<Routes><Route path="/install" element={<Navigate to="/" replace/>}/><Route path="/login" element={user?<Navigate to="/"/>:<Login settings={settings}/>}/><Route path="/" element={<Guard user={user}><Home settings={settings}/></Guard>}/><Route path="/sources" element={<Guard user={user}><Sources/></Guard>}/><Route path="/source/:key" element={<Guard user={user}><Source/></Guard>}/><Route path="/detail/:sourceKey/:videoId" element={<Guard user={user}><Detail/></Guard>}/><Route path="/player/:sourceKey/:videoId/:episodeId" element={<Guard user={user}><Player settings={settings}/></Guard>}/><Route path="/search" element={<Guard user={user}><Search/></Guard>}/><Route path="/favorites" element={<Guard user={user}><Favorites/></Guard>}/><Route path="/history" element={<Guard user={user}><History/></Guard>}/><Route path="/profile" element={<Guard user={user}>{user&&<Profile user={user}/>}</Guard>}/><Route path="/admin" element={<Guard user={user} admin><AdminDashboard/></Guard>}/><Route path="/admin/settings" element={<Guard user={user} admin><AdminSettings/></Guard>}/><Route path="/admin/sources" element={<Guard user={user} admin><AdminSources/></Guard>}/><Route path="/admin/collection" element={<Guard user={user} admin><CollectionCenter/></Guard>}/><Route path="/admin/categories" element={<Guard user={user} admin><CategoryManager/></Guard>}/><Route path="/admin/videos" element={<Guard user={user} admin><VideoManager/></Guard>}/><Route path="/admin/editor" element={<Guard user={user} admin><SourceEditor/></Guard>}/><Route path="/admin/users" element={<Guard user={user} admin><AdminUsers/></Guard>}/><Route path="/admin/history" element={<Guard user={user} admin><AdminList kind="history" title="观看统计"/></Guard>}/><Route path="/admin/danmaku" element={<Guard user={user} admin><AdminDanmaku/></Guard>}/><Route path="/admin/errors" element={<Guard user={user} admin><AdminList kind="errors" title="播放错误"/></Guard>}/><Route path="/admin/logs" element={<Guard user={user} admin><AdminList kind="logs" title="系统日志"/></Guard>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes>{chrome&&<footer>{settings.footerText||settings.copyrightText||'大彪TV · 仅用于播放你拥有授权的内容'}</footer>}</>}
